"use client";

import { useRef, useState, type KeyboardEvent } from "react";
import Link, { SourceLink } from "@/components/app-link";
import course from "@/lib/content/water-foundation-course.json";
import { chapterAtTime, courseTime, WATER_FOUNDATION } from "@/lib/learning/water-foundation";
import styles from "./water-foundation-course.module.css";

const tabs = ["Overview", "Transcript", "Sources", "Continue learning"] as const;

export function WaterFoundationCourse() {
  const video = useRef<HTMLVideoElement>(null);
  const [chapterIndex, setChapterIndex] = useState(0);
  const [tab, setTab] = useState<number>(0);
  const chapter = course.chapters[chapterIndex];
  function seek(time: number) {
    if (video.current) video.current.currentTime = time;
    setChapterIndex(chapterAtTime(course.chapters, time));
  }
  function updateChapter() {
    const time = video.current?.currentTime ?? 0;
    setChapterIndex(chapterAtTime(course.chapters, time));
  }
  function moveTab(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    let next = index;
    if (event.key === "ArrowRight") next = (index + 1) % tabs.length;
    else if (event.key === "ArrowLeft") next = (index + tabs.length - 1) % tabs.length;
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = tabs.length - 1;
    else return;
    event.preventDefault();
    setTab(next);
    document.getElementById(`water-tab-${next}`)?.focus();
  }
  return <article className={styles.course}>
    <nav aria-label="Breadcrumb" className={styles.breadcrumb}><Link href="/learn/cultural-intelligence">Cultural Intelligence</Link><span aria-hidden="true"> / </span><span>The Water We Swim In</span></nav>
    <header className={styles.header}>
      <p className={styles.eyebrow}>People, Access and Culture</p>
      <h1>The Water We Swim In</h1>
      <p className={styles.intro}>Recognize the cultural assumptions that shape our work—and use that understanding to improve services, workplace decisions and organizational responsibility.</p>
      <p className={styles.meta}>For staff and leaders · About 1 hour · 12 chapters</p>
    </header>
    <div className={styles.watch}>
      <div className={styles.main}>
        <video ref={video} className={styles.video} controls controlsList="nodownload" playsInline preload="metadata" poster={WATER_FOUNDATION.poster} onTimeUpdate={updateChapter} onSeeked={updateChapter} aria-label="Watch The Water We Swim In">
          <source src={WATER_FOUNDATION.video} type="video/mp4" />
          <track kind="captions" src={WATER_FOUNDATION.captions} srcLang="en" label="English" />
          <p>The transcript is available below.</p>
        </video>
        <section className={styles.context} aria-labelledby="chapter-heading">
          <p className={styles.eyebrow}>Chapter {chapter.number}</p>
          <h2 id="chapter-heading">{chapter.title}</h2>
          <p>{chapter.objective}</p>
          <details key={chapter.number}><summary>Apply this to your work</summary><p>{chapter.application}</p><p>Pause whenever you need time to reflect or discuss.</p></details>
        </section>
      </div>
      <nav className={styles.chapters} aria-label="Course chapters">
        <h2>Chapters</h2>
        <ol>{course.chapters.map((item, index) => <li key={item.number}><button type="button" aria-current={index === chapterIndex ? "step" : undefined} onClick={() => seek(item.start)}><span className={styles.number}>{String(item.number).padStart(2, "0")}</span><span>{item.title}<small>{courseTime(item.start)}</small></span></button></li>)}</ol>
      </nav>
    </div>
    <div className={styles.tabs} role="tablist" aria-label="Course materials">{tabs.map((name, index) => <button key={name} id={`water-tab-${index}`} type="button" role="tab" aria-selected={tab === index} aria-controls={`water-panel-${index}`} tabIndex={tab === index ? 0 : -1} onClick={() => setTab(index)} onKeyDown={event => moveTab(event, index)}>{name}</button>)}</div>
    {tabs.map((name, index) => <section key={name} id={`water-panel-${index}`} role="tabpanel" aria-labelledby={`water-tab-${index}`} hidden={tab !== index} tabIndex={0} className={styles.panel}>
      {index === 0 && <>
        <h2>Turn the lens toward our own institution</h2>
        <p>This course examines how historically dominant white cultural norms in American and Minnesota institutions can shape what seems normal, credible or fair. It connects that examination to community perspectives, disability and language access, intercultural communication, workforce decisions and leadership responsibility.</p>
        <p>Cultural patterns are a starting point for inquiry. They do not tell us what any individual believes or needs. Responsive practice combines evidence, direct listening and a willingness to change how the organization works.</p>
        <h3>By the end, you will be able to</h3>
        <ul><li>Identify assumptions in a service or workplace decision and distinguish evidence from interpretation.</li><li>Use community perspectives and cultural briefs to ask better questions without stereotyping people.</li><li>Choose a practical organizational response, identify who can act and decide how to check whether access improves.</li></ul>
        <h3>Connect the learning</h3>
        <div className={styles.resources}>{course.learning_destinations.filter(item => ["/minnesota-communities/american", "/minnesota-communities/minnesota", "/minnesota-communities"].includes(item.url)).map(item => <Link key={item.url} href={item.url}>{item.title}</Link>)}</div>
        <p className={styles.note}>{course.case_note}</p>
      </>}
      {index === 1 && <><h2>Course transcript</h2>{course.scenes.map(scene => <section className={styles.transcript} key={scene.id}><h3><button type="button" onClick={() => seek(scene.start)} aria-label={`Go to ${scene.title}`}>{courseTime(scene.start)} · {scene.title}</button></h3>{scene.narration.split("\n\n").map((paragraph, paragraphIndex) => <p key={paragraphIndex}>{paragraph}</p>)}</section>)}</>}
      {index === 2 && <><h2>Sources and context</h2><p>Dates and scope matter. Historical findings provide context; they are not presented as current DHS statistics.</p><ul className={styles.sourceList}>{course.sources.map(source => <li key={source.url}><h3><SourceLink original href={source.url}>{source.title}</SourceLink></h3><p className={styles.meta}>{source.date}</p><p>{source.scope}</p>{source.reading_note && <p>{source.reading_note}</p>}</li>)}</ul></>}
      {index === 3 && <><h2>Continue learning and put it into practice</h2><p>Use the briefs to prepare questions, then explore the tools and courses that match your responsibilities.</p>{[...new Set(course.learning_destinations.map(item => item.group))].map(group => <section key={group}><h3>{group}</h3><ul className={styles.sourceList}>{course.learning_destinations.filter(item => item.group === group).map(item => <li key={item.url}><Link href={item.url}>{item.title}</Link><p>{item.scope}</p></li>)}</ul></section>)}</>}
    </section>)}
  </article>;
}

import Link from "@/components/app-link";
import { WATER_FOUNDATION } from "@/lib/learning/water-foundation";
import styles from "./water-foundation-course.module.css";

export function WaterFoundationFeature() {
  return <section className={styles.feature} aria-labelledby="water-foundation-title">
    <div>
      <p className={styles.eyebrow}>Featured course · About 1 hour</p>
      <h2 id="water-foundation-title">The Water We Swim In</h2>
      <p>Examine how familiar cultural assumptions shape public services, workplace decisions and whose experience counts. Connect that understanding to culturally responsive action.</p>
      <Link className={styles.primary} href={WATER_FOUNDATION.href}>Open the course</Link>
      <p className={styles.related}><Link href="/learn/water-we-swim-in/collection">Explore the briefs and practice collection</Link></p>
    </div>
    <video className={styles.video} controls controlsList="nodownload" playsInline preload="metadata" poster={WATER_FOUNDATION.poster} aria-label="Watch The Water We Swim In">
      <source src={WATER_FOUNDATION.video} type="video/mp4" />
      <track kind="captions" src={WATER_FOUNDATION.captions} srcLang="en" label="English" />
      <p><Link href={WATER_FOUNDATION.href}>Open the course and transcript</Link></p>
    </video>
  </section>;
}

"use client";

import Image from "next/image";
import Link from "@/components/app-link";
import { usePathname } from "next/navigation";
import { useRef, useState } from "react";
import { ContextSwitcher } from "@/components/program-context";
import { SharePage } from "@/components/share-page";
import { EditableSurfaceEditor } from "@/components/editable-surface-editor";
import type { PreparedEditableSurface } from "@/components/editable-surface";
import type { EditableSurfaceLink, EditableSurfaceValues } from "@/lib/content/editable-surface-contract";
import { displayProgramName } from "@/lib/brand/legacy-program-name";

function textValue(values: EditableSurfaceValues, key: string): string {
  return typeof values[key] === "string" ? values[key] as string : "";
}
function linksValue(values: EditableSurfaceValues, key: string): EditableSurfaceLink[] {
  const value = values[key];
  return Array.isArray(value) && (value.length === 0 || (typeof value[0] === "object" && value[0] !== null && "href" in value[0]))
    ? value as EditableSurfaceLink[] : [];
}

export function SiteHeader({ headerSurface, contextSurface }: {
  headerSurface: PreparedEditableSurface;
  contextSurface: PreparedEditableSurface;
}) {
  const pathname = usePathname();
  const [menuOpen, setMenuOpen] = useState(false);
  const menuButton = useRef<HTMLButtonElement>(null);
  const primaryNavigation = [...linksValue(headerSurface.values, "primaryNavigation")];
  const priorDefaultRoutes = ["/", "/start", "/ask", "/areas", "/learn", "/practice", "/one-dsd", "/support"];
  if (primaryNavigation.map(route => route.href).join("|") === priorDefaultRoutes.join("|")) {
    primaryNavigation.splice(7, 0, { label: "Amplify Equity", href: "/one-dsd/amplify" });
  }
  const personalNavigation = linksValue(headerSurface.values, "personalNavigation");
  const isCurrent = (href: string) => href === "/" ? pathname === "/" : (href === "/one-dsd" && pathname.startsWith("/one-dsd/amplify")) ? false : pathname === href || pathname.startsWith(href + "/") ||
    (href === "/learn" && ["/library", "/resources", "/courses"].some(base => pathname === base || pathname.startsWith(base + "/")));

  return <header className="program-header" onKeyDown={event => {
    if (event.key === "Escape" && menuOpen) { setMenuOpen(false); menuButton.current?.focus(); }
  }}>
    {headerSurface.canEdit || contextSurface.canEdit ? <div className="wrap pt-3">
      {headerSurface.canEdit ? <EditableSurfaceEditor definition={headerSurface.definition} scope={headerSurface.scope} currentValues={headerSurface.values} inherited={headerSurface.published?.isInherited ?? false} /> : null}
      {contextSurface.canEdit ? <EditableSurfaceEditor definition={contextSurface.definition} scope={contextSurface.scope} currentValues={contextSurface.values} inherited={contextSurface.published?.isInherited ?? false} /> : null}
    </div> : null}
    <div className="program-brand-row wrap">
      <Link href="/" className="program-brand-link">
        <span className="program-agency-brand"><Image src="/images/dhs-logo.png" alt="Minnesota Department of Human Services" width={319} height={68} priority /><span className="program-division-label">Disability Services Division</span></span>
        {headerSurface.available ? <span className="program-wordmark">{displayProgramName(textValue(headerSurface.values, "programName"))}</span> : null}
      </Link>
      <div className="program-header-actions">
        <SharePage compact />
        {contextSurface.available ? <ContextSwitcher /> : null}
        {headerSurface.available ? <button ref={menuButton} type="button" className="program-menu-toggle" aria-expanded={menuOpen} aria-controls="program-primary-navigation" onClick={() => setMenuOpen(open => !open)}>{menuOpen ? "Close menu" : "Menu"}</button> : null}
      </div>
    </div>
    {headerSurface.available ? <nav id="program-primary-navigation" aria-label="Primary" className={menuOpen ? "program-navigation is-open" : "program-navigation"}>
      <ul className="wrap" onClick={event => { if ((event.target as HTMLElement).closest("a")) setMenuOpen(false); }}>
        {primaryNavigation.map(route => <li key={route.href}>
          <Link href={route.href} aria-current={isCurrent(route.href) ? "page" : undefined} className={isCurrent(route.href) ? "primary-nav-link primary-nav-link--current" : "primary-nav-link"}>{route.label}</Link>
        </li>)}
        {personalNavigation.map(route => <li className="program-personal-link" key={route.href}>
          <Link href={route.href} aria-current={isCurrent(route.href) ? "page" : undefined} className={isCurrent(route.href) ? "primary-nav-link primary-nav-link--current" : "primary-nav-link"}>{route.label}</Link>
        </li>)}
      </ul>
    </nav> : null}
  </header>;
}

import Link from "@/components/app-link";
import { RESOURCE_THEMES } from "@/lib/content/resource-organization";

export type ResourceFormatView = "library" | "learning" | "reading" | "listening";

export function ResourceFormatLinks({ theme, current }: { theme?: string; current: ResourceFormatView }) {
  const selected = RESOURCE_THEMES.find(item => item.id === theme);
  const suffix = selected ? `?theme=${selected.id}` : "";
  const links = [
    { id: "library", href: "/library", title: "Learning, tools and guidance" },
    { id: "learning", href: "/learn", title: "Courses and practice" },
    { id: "reading", href: "/learn/sources", title: "Books and research" },
    { id: "listening", href: "/audio-library", title: "Recordings and podcasts" },
  ];
  return <nav aria-label={selected ? `More ways to explore ${selected.title}` : "Ways to explore resources"} className="my-6 flex flex-wrap gap-x-6 gap-y-2">
    {links.map(link => <Link key={link.id} href={link.href + suffix} aria-current={link.id === current ? "page" : undefined} className="inline-flex min-h-11 items-center font-semibold text-[var(--blue)] underline underline-offset-4">{link.title}</Link>)}
  </nav>;
}

import Link from "@/components/app-link";
import { RESOURCE_THEMES } from "@/lib/content/resource-organization";

export function ResourceThemeNav({ basePath, className, gridClassName }: { basePath: "/learn" | "/library" | "/learn/sources" | "/audio-library"; className?: string; gridClassName?: string }) {
  return <section className={className} aria-labelledby="resource-themes-title">
    <h2 id="resource-themes-title">Explore by theme</h2>
    <p>Find related learning, useful tools, and ways to apply them in your work.</p>
    <ul className={gridClassName}>{RESOURCE_THEMES.map(theme => <li key={theme.id}>
      <h3><Link href={`${basePath}?theme=${theme.id}`}>{theme.title}</Link></h3>
      <p>{theme.description}</p>
    </li>)}</ul>
  </section>;
}

import Link from "@/components/app-link";
import type { ContentItem } from "@/lib/content/types";

/** One set of entry links into existing resources; no additional copies of content. */
export function ResourceStartingPoints({ className, items, toolkitAvailable }: { className?: string; items: readonly ContentItem[]; toolkitAvailable: boolean }) {
  const available = new Set(items.filter(item => item.status === "approved").map(item => item.id));
  const toolkitLinks = [
    ...(toolkitAvailable ? [{ href:"/learn/equity-toolkit", label:"Start with the toolkit guide" }] : []),
    ...(available.has("ext-dhs-equity-toolkit") ? [{ href:"/library/ext-dhs-equity-toolkit", label:"Read the original DHS toolkit source" }] : []),
    ...(available.has("course-dhs-equity-analysis-toolkit") ? [{ href:"/courses/dhs-equity-analysis-toolkit", label:"Learn with the companion course" }] : []),
  ];
  return <section className={className} aria-labelledby="resource-start-title">
    <h2 id="resource-start-title">What would help with your work?</h2>
    <p>Go straight to a useful tool, prepare a piece of work, or build your understanding. Choose the support that fits your question.</p>
    <div className="resource-entry-grid">
      {toolkitLinks.length ? <article><h3><Link href={toolkitLinks[0].href}>Examine a policy or decision</Link></h3><p>Consider who is affected, compare choices, and prepare a reasoned recommendation.</p><ul>{toolkitLinks.map(link=><li key={link.href}><Link href={link.href}>{link.label}</Link></li>)}</ul></article> : null}
      <article><h3><Link href="/practice-guides/clearer-processes">Make information easier to use</Link></h3><p>Help people understand a notice, form, or next step without losing the meaning.</p><ul>{available.has("ja-plain-language") ? <li><Link href="/library/ja-plain-language">Use the plain language and access checklist</Link></li> : null}{available.has("self-directed-F16") ? <li><Link href="/learning/self-directed/index.html?course=F16">Learn plain language through practice</Link></li> : null}<li><Link href="/practice-guides/clearer-processes">Work through a process improvement</Link></li></ul></article>
      <article><h3><Link href="/practice">Prepare for a real situation</Link></h3><p>Find a starting point for a meeting, service change, community conversation, or review.</p><ul><li><Link href="/practice-guides/inclusive-meetings">Prepare accessible participation</Link></li><li><Link href="/practice">Choose a guided work path</Link></li><li><Link href="/practice-guides/review-a-change">Learn from what changed</Link></li></ul></article>
    </div>
  </section>;
}

import Link from "@/components/app-link";
import { RESOURCE_PATHWAYS, publishedPathwayChoices } from "@/lib/content/resource-pathways";
import type { ContentItem } from "@/lib/content/types";
import { selfDirectedHref } from "@/lib/content/self-directed";

export function ResourceThemePathway({ theme, items, className }: { theme: string; items: readonly ContentItem[]; className?: string }) {
  const pathway = RESOURCE_PATHWAYS[theme];
  if (!pathway) return null;
  const choices = publishedPathwayChoices(pathway, items);
  if (!choices.length) return null;
  return <section className={className} aria-labelledby="resource-theme-practice-title">
    <h2 id="resource-theme-practice-title">{pathway.title}</h2>
    <p>{pathway.introduction}</p>
    <div className="resource-entry-grid">{choices.map(choice => <article key={choice.label}>
      <h3>{choice.label}</h3><p>{choice.purpose}</p>
      <ul>{choice.resources.map(item => <li key={item.id}><Link href={selfDirectedHref(item.id) ?? (item.id.startsWith("course-") ? "/courses/" + encodeURIComponent(item.id.slice(7)) : "/library/" + encodeURIComponent(item.id))}>{item.title}</Link></li>)}</ul>
    </article>)}</div>
    <h3>What you can take back to your work</h3><p>{pathway.workProduct}</p><p>{pathway.intendedBenefit}</p>
  </section>;
}

import { SourceLink } from "@/components/app-link";
import { downloadHref, type DownloadKind, type DownloadScope } from "@/lib/downloads/catalog";
import { SharePage } from "@/components/share-page";
import { DOWNLOAD_FORMATS, DOWNLOAD_FORMAT_DETAILS, FALLBACK_DOWNLOAD_FORMATS, FALLBACK_DOWNLOAD_FORMAT_DETAILS } from "@/lib/downloads/model";

type ResourceDownloadsProps = {
  kind: DownloadKind;
  id: string;
  /** What the control calls the thing being downloaded. */
  noun?: string;
  /** The program view the page is showing, so the file matches the page. */
  scope?: DownloadScope;
  compact?: boolean;
  appearance?: "buttons" | "links";
  /** Also offer share controls (copy link, email, device share). On by default; pass false where the page already shows them. */
  share?: boolean;
  /** Page to share instead of the current one. */
  shareHref?: string;
  shareTitle?: string;
};

/**
 * Word, Excel, PowerPoint and PDF copies of a resource, built from the same published
 * wording the page shows, plus ways to share it. Available to everyone; nothing personal is attached.
 */
export function ResourceDownloads({ kind, id, noun = "resource", scope, compact = false, appearance = "buttons", share = true, shareHref, shareTitle }: ResourceDownloadsProps) {
  const linkClassName = appearance === "links" ? "resource-download-text-link" : "btn btn--light !min-h-0 !px-3 !py-1 !text-sm";
  return (
    <div
      data-resource-download="true"
      role="group"
      aria-label={`Download this ${noun}`}
      className={compact ? "inline-flex flex-wrap items-center gap-2 print:hidden" : "mt-4 flex flex-wrap items-center gap-2 print:hidden"}
    >
      <span className="text-sm font-bold">Download this {noun}:</span>
      {DOWNLOAD_FORMATS.map((format) => (
        <SourceLink
          key={format}
          className={linkClassName}
          href={downloadHref(kind, id, format, scope)}
          download
          aria-label={`Download this ${noun} as ${DOWNLOAD_FORMAT_DETAILS[format].label}`}
        >
          {DOWNLOAD_FORMAT_DETAILS[format].label}
        </SourceLink>
      ))}
      {FALLBACK_DOWNLOAD_FORMATS.map((format) => (
        <SourceLink
          key={format}
          className={linkClassName}
          href={downloadHref(kind, id, format, scope)}
          download
          aria-label={`Download this ${noun} as ${FALLBACK_DOWNLOAD_FORMAT_DETAILS[format].label}`}
        >
          {FALLBACK_DOWNLOAD_FORMAT_DETAILS[format].label}
        </SourceLink>
      ))}
      {share ? <SharePage compact noun={noun} href={shareHref} title={shareTitle} /> : null}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { PRODUCT_CONTEXT_COOKIE, resolveProductContext, type ProductContextId } from "@/lib/product/federation";
import { currentShareLocation, shareLink } from "@/lib/product/share-link";

type SharePageProps = {
  /** Subject line and heading for the shared item; defaults to the document title. */
  title?: string;
  /** Local path to share instead of the current page, for example a podcast anchor. */
  href?: string;
  /** What the control calls the thing being shared. */
  noun?: string;
  compact?: boolean;
};

/** The program view in effect for this visitor: an explicit view in the address wins, then the saved preference. */
function currentContext(): ProductContextId {
  try {
    const fromAddress = new URLSearchParams(window.location.search).get("view");
    if (fromAddress) {
      const normalized = fromAddress.trim().toLowerCase().replace(/-/g, "_");
      if (normalized === "one_dsd" || normalized === "dsd") return "one_dsd";
      if (normalized === "one_dhs" || normalized === "dhs") return "one_dhs";
    }
    const cookie = document.cookie.split(";").map(part => part.trim()).find(part => part.startsWith(`${PRODUCT_CONTEXT_COOKIE}=`));
    return resolveProductContext(cookie?.slice(PRODUCT_CONTEXT_COOKIE.length + 1));
  } catch {
    return resolveProductContext(undefined);
  }
}

/**
 * Copies a link that opens exactly this page or resource, in the same program
 * view, with nothing personal attached. Available to everyone.
 */
export function SharePage({ title, href, noun = "page", compact = false }: SharePageProps) {
  const [message, setMessage] = useState("");

  const link = () => {
    const current = currentShareLocation();
    const target = href ? new URL(href, current.origin) : null;
    const location = target ? { origin: current.origin, pathname: target.pathname, search: target.search, hash: target.hash } : current;
    return shareLink(location, currentContext());
  };
  const subject = () => title ?? document.title;

  const copy = async () => {
    const value = link();
    try {
      await navigator.clipboard.writeText(value);
      setMessage(`Link copied. It opens this ${noun} only.`);
    } catch {
      setMessage(value);
    }
  };
  const email = () => {
    window.location.href = `mailto:?subject=${encodeURIComponent(subject())}&body=${encodeURIComponent(`I thought you might find this useful:\n\n${subject()}\n${link()}`)}`;
  };

  const [canShare, setCanShare] = useState(false);
  useEffect(() => { setCanShare(typeof navigator !== "undefined" && typeof navigator.share === "function"); }, []);
  const deviceShare = async () => {
    try {
      await navigator.share({ title: subject(), url: link() });
    } catch {
      /* the person closed the share sheet */
    }
  };

  const buttonClass = compact ? "btn btn--light !min-h-0 !px-3 !py-1 !text-xs" : "btn";
  return (
    <div className={compact ? "inline-flex flex-wrap items-center gap-2" : "mt-4 flex flex-wrap items-center gap-3"} data-share-page="true">
      <button type="button" className={buttonClass} onClick={() => void copy()}>{compact ? "Copy link" : `Share this ${noun}`}</button>
      <button type="button" className={compact ? buttonClass : "btn btn--light"} onClick={email}>{compact ? "Email link" : "Share by email"}</button>
      {canShare ? <button type="button" className={compact ? buttonClass : "btn btn--light"} onClick={() => void deviceShare()}>More ways to share</button> : null}
      {message ? <span role="status" className="text-sm break-all">{message}</span> : null}
    </div>
  );
}

import Link from "@/components/app-link";
import { WORK_EXAMPLES } from '@/lib/program/work-examples';
import styles from './work-examples.module.css';

export function WorkExamples({dsd=false}:{dsd?:boolean}) {
  return <section className={styles.section} id="work-examples" aria-labelledby="work-examples-title">
    <p className={styles.eyebrow}>Ideas you can put to work</p>
    <h2 id="work-examples-title">Start with a situation that feels familiar</h2>
    <p>These practice examples connect useful resources with everyday decisions. Choose one to see what you could do and how you might learn from it.</p>
    {WORK_EXAMPLES.map(example=><details className={styles.example} key={example.id} open={example.id === 'notice'} name="work-example">
      <summary>{example.title}</summary>
      <div className={styles.body}>
        <p>{dsd && example.dsdSituation ? example.dsdSituation : example.situation}</p>
        <ol className={styles.steps}>{example.links.map(link=><li key={link.href}><Link href={link.href}>{link.label}</Link><p>{link.purpose}</p></li>)}</ol>
        <div className={styles.outcome}><h3>What you can take back</h3><p>{example.takeaway}</p><h3>How you’ll know more</h3><p>{example.check}</p></div>
      </div>
    </details>)}
    <p className={styles.note}>Use the resources that fit your responsibility. Confirm applicable requirements and the appropriate review before changing a service or policy.</p>
  </section>;
