sible.map(course=><li key={course.id} className="border-t border-line pt-4"><p className="kicker">{course.level||course.series}</p><h3 className="text-xl font-extrabold"><Link href={course.href}>{course.title}</Link></h3><p>{course.summary}</p><p className="text-sm">{course.detail}</p></li>)}</ul>:<p>No courses match these choices. Try a broader subject or clear the filters.</p>}{expanded?<nav aria-label="Course result pages" className="flex flex-wrap gap-6 mt-6">{page>1?<Link href={pageHref(page-1)}>Previous results</Link>:null}<span>Page {page} of {totalPages}</span>{page<totalPages?<Link href={pageHref(page+1)}>Next results</Link>:null}</nav>:<p className="mt-6"><Link href="/courses?browse=all">Browse all {all.length} courses</Link></p>}</section><p className="text-sm">{TRAINING_CREDIT_NOTICE}</p></div></div>;
