"use client";

import Link from "@/components/app-link";
import { useState } from "react";
import { suggestedPath, type StartAnswers } from "@/lib/content/leadership-journey";
import styles from "./collections.module.css";

type Path = { slug: string; title: string; description: string };
type Choice = boolean | undefined;

function YesNo({ legend, name, value, onChange }: { legend: string; name: string; value: Choice; onChange: (value: boolean) => void }) {
  return <fieldset className="mt-4">
    <legend className="font-bold">{legend}</legend>
    <div className="mt-2 flex flex-wrap gap-x-8 gap-y-2">
      <label className="inline-flex items-center gap-2"><input type="radio" name={name} checked={value === true} onChange={() => onChange(true)} /> Yes</label>
      <label className="inline-flex items-center gap-2"><input type="radio" name={name} checked={value === false} onChange={() => onChange(false)} /> No</label>
    </div>
  </fieldset>;
}

/**
 * A few questions about a person's own work that suggest where to start. The answers stay on the
 * page: they are not saved, counted or sent, and every path remains open whatever is suggested.
 */
export function LeadingStartChooser({ paths }: { paths: readonly Path[] }) {
  const [supervises, setSupervises] = useState<Choice>();
  const [guidesProgram, setGuidesProgram] = useState<Choice>();
  const [firstYear, setFirstYear] = useState<Choice>();
  const [supervisesSupervisors, setSupervisesSupervisors] = useState<Choice>();
  const [setsDirection, setSetsDirection] = useState<Choice>();

  const answered = supervises === false ? guidesProgram !== undefined
    : supervises === true && supervisesSupervisors === true ? setsDirection !== undefined
    : supervises === true && supervisesSupervisors === false ? firstYear !== undefined
    : false;
  const answers: StartAnswers = { supervises: supervises === true, guidesProgram, firstYear, supervisesSupervisors, setsDirection };
  const suggestion = answered ? paths.find(path => path.slug === suggestedPath(answers)) : undefined;

  return <form onSubmit={event => event.preventDefault()} aria-label="Find a starting point">
    <YesNo legend="Do you supervise people?" name="supervises" value={supervises} onChange={value => { setSupervises(value); setGuidesProgram(undefined); setFirstYear(undefined); setSupervisesSupervisors(undefined); setSetsDirection(undefined); }} />
    {supervises === false ? <YesNo legend="Do you guide a program, policy or project?" name="guides-program" value={guidesProgram} onChange={setGuidesProgram} /> : null}
    {supervises === true ? <YesNo legend="Do the people you supervise also supervise others?" name="supervises-supervisors" value={supervisesSupervisors} onChange={value => { setSupervisesSupervisors(value); setFirstYear(undefined); setSetsDirection(undefined); }} /> : null}
    {supervises === true && supervisesSupervisors === false ? <YesNo legend="Is this your first year of supervising?" name="first-year" value={firstYear} onChange={setFirstYear} /> : null}
    {supervises === true && supervisesSupervisors === true ? <YesNo legend="Do you set direction for a division or a function across the agency?" name="sets-direction" value={setsDirection} onChange={setSetsDirection} /> : null}
    <div role="status" aria-live="polite" className="mt-4">
      {suggestion ? <p className={styles.plain}>A good place to start: <Link href={`/leading/paths/${suggestion.slug}`}>{suggestion.title}</Link>. {suggestion.description} It is only a suggestion. Every path is open to you.</p> : null}
    </div>
    <p className={`${styles.plain} mt-2`}>Your answers stay on this page. They are not saved or sent anywhere.</p>
  </form>;
}

"use client";
import { useEffect,useState } from "react";
import Link from "@/components/app-link";
export function CourseResume({courseId,lessons}:{courseId:string;lessons:Array<{id:string;title:string}>}) {
  const [resume,setResume]=useState<string>();const [completed,setCompleted]=useState(0);const [error,setError]=useState("");
  useEffect(()=>{let active=true;Promise.resolve().then(()=>{if(!active)return;try{const id=localStorage.getItem(`pac-course-resume:${courseId}`);if(lessons.some(lesson=>lesson.id===id))setResume(id!);setCompleted(lessons.filter(lesson=>{try{return JSON.parse(localStorage.getItem(`pac-course:${courseId}:${lesson.id}`)??"{}").completed===true;}catch{setError("Some saved progress could not be opened. You can choose any lesson below.");return false;}}).length);}catch{setError("Your saved progress could not be opened. You can choose any lesson below.");}});return()=>{active=false;};},[courseId,lessons]);
  return <div><Link className="button" href={`/courses/${courseId}/${resume??lessons[0].id}`}>{resume?"Continue learning":"Start learning"}</Link>{error?<p role="status">{error}</p>:null}{completed?<p>{completed} of {lessons.length} lessons complete</p>:null}</div>;
}

import Image from "next/image";
import { selfDirectedPresentation } from "@/lib/content/self-directed-covers";
import Link from "@/components/app-link";
import { AuthorityPill } from "@/components/ui";
import { resourceLearningLevel } from "@/lib/content/resource-organization";
import { progressionLabel, resourceProgressionLevel } from "@/lib/content/progression";
import type { ContentItem } from "@/lib/content/types";
import styles from "./learning-tile.module.css";
import { ResourceRemove } from "@/components/resource-tools";
import { selfDirectedHref } from "@/lib/content/self-directed";
import { resourceStudyHref } from "@/lib/client/resource-study-links";

type LearningTileProps = {
  item: ContentItem;
  href?: string;
  presentation?: { imageSrc: string; imageAlt: string; summary: string };
  /** Signed-in consultant: show the small remove control on the tile. */
  owner?: boolean;
  /** Learning discovery can show course level without changing other card uses. */
  showLevel?: boolean;
};

export function LearningTile({ item, presentation, href, owner = false, showLevel = false }: LearningTileProps) {
  presentation = selfDirectedPresentation(item.id, item.summary) ?? presentation;
  const level = showLevel ? resourceLearningLevel(item) : null;
  const progression = showLevel ? resourceProgressionLevel(item.id) ?? (level ? ({ foundation: "foundations", intermediate: "applying", advanced: "leading" } as const)[level] : null) : null;
  const titleId = `learning-title-${item.id}`;
  const hasImage = Boolean(presentation?.imageSrc);
  const studyPath = process.env.GEMINI_API_KEY?.trim() ? selfDirectedHref(item.id) : undefined;
  return <article data-learning-id={item.id} style={owner ? { position: "relative" } : undefined}>
    {owner ? <div style={{ position: "absolute", top: 8, right: 8, zIndex: 2 }}><ResourceRemove contentItemId={item.id} title={item.title} compact /></div> : null}
    <Link href={href ?? `/library/${item.id}`} className={`${styles.tile} ${hasImage ? "" : styles.textOnly}`} aria-labelledby={titleId}>
      {hasImage ? <div className={styles.media}>
        <Image src={presentation!.imageSrc} alt={presentation!.imageAlt} fill sizes="(max-width: 460px) 90vw, (max-width: 760px) 35vw, (max-width: 1000px) 42vw, 240px" style={{ objectFit: "contain" }} unoptimized />
      </div> : null}
      <div className={styles.copy}>
        {progression ? <p className={styles.level} data-learning-level={level ?? progression}>{progressionLabel(progression)}</p> : null}
        <h3 id={titleId} className={styles.title}>{item.title}</h3>
        <p className={styles.summary}>{presentation?.summary || item.summary}</p>
        <div className={styles.meta}><AuthorityPill authority={item.authority} /></div>
      </div>
    </Link>
    {studyPath ? <Link href={resourceStudyHref(studyPath)} prefetch={false} className="mt-2 inline-block text-sm font-semibold underline underline-offset-4" aria-label={`Study ${item.title}`}>Study this course</Link> : null}
  </article>;
}
